% !TEX program = lualatex
\documentclass[11pt,a4paper]{article}
\input{../../../_notes-shared/preamble.tex}

\pagestyle{fancy}
\fancyhf{}
\fancyhead[L]{\small HKDSE Physics --- Electromagnetic induction}
\fancyhead[R]{\small Active Physics Book~4, Ch.~24}
\fancyfoot[C]{\thepage}
\renewcommand{\headrulewidth}{0.4pt}

\title{\textbf{Electromagnetic Induction}\\[0.35em]
\large HKDSE Physics --- Electricity \& Magnetism}
\author{Teaching notes aligned with \emph{Active Physics} Book~4, Chapter~24\\
Worked examples from HKDSE Paper~1A and QB\_407}
\date{}

\begin{document}
\maketitle
\tableofcontents
\vspace{0.5em}

\begin{mdframed}[style=tipbox]
\noindent\textbf{How these notes work.}
We start from the idea that a changing magnetic ``amount of field through a loop''
creates an emf, then build Faraday's and Lenz's laws, motional emf, and simple
generators. Blue boxes = worked DSE / QB examples. Orange boxes at the end =
practice (answers last). Theory and example boxes never split across a page break.
\end{mdframed}

%======================================================================
\section{The everyday observation}

Move a bar magnet into a coil connected to a galvanometer: the needle kicks.
Hold the magnet still inside the coil: the needle returns to zero.
Pull the magnet out: the needle kicks the other way.
Spin a bicycle dynamo: a lamp lights.

Nothing in the coil is ``touching'' the magnet in a mechanical sense, yet an
\textbf{electromotive force (emf)} appears. That phenomenon is
\textbf{electromagnetic induction}.

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mix-up.}
A \emph{steady} magnetic field through a coil does \emph{not} induce an emf.
Induction cares about \textbf{change} (or relative motion that changes the
flux), not about ``having a field nearby''.
\end{mdframed}

%======================================================================
\section{Magnetic flux}

\subsection{What flux measures}
Think of magnetic field lines as rain falling through a window.
\textbf{Magnetic flux} $\Phi$ measures how many field lines pass through an area.

For a uniform field $B$ through a flat area $A$,
\[
\Phi = B A \cos\theta = B_\perp A,
\]
where $\theta$ is the angle between $\vec B$ and the \textbf{normal} to the area
(the direction ``straight out'' of the face of the loop).

\begin{center}
\begin{tikzpicture}[scale=1.05]
  % area
  \draw[thick,fill=blue!8] (0,0) -- (2.4,0.4) -- (2.4,2.0) -- (0,1.6) -- cycle;
  \node[font=\small] at (1.2,1.0) {$A$};
  % normal
  \draw[-{Latex},very thick,blue!50!black] (1.2,1.0) -- (1.2,2.9)
    node[above,font=\small] {normal};
  % B
  \draw[-{Latex},very thick,posC] (1.2,1.0) -- (2.6,2.6)
    node[above right,font=\small] {$\vec B$};
  \draw[dashed] (1.2,1.0) -- (2.6,1.0);
  \draw (1.7,1.0) arc (0:45:0.5);
  \node[font=\scriptsize] at (1.95,1.25) {$\theta$};
  \node[below,align=center,font=\small] at (1.2,-0.55)
    {$\Phi = BA\cos\theta$\\[0.2em]
     max when $\theta=0$ (field $\perp$ area); zero when $\theta=90^\circ$};
\end{tikzpicture}
\end{center}

\begin{itemize}
  \item Unit of $\Phi$: \textbf{weber} (Wb). $1\,\mathrm{Wb}=1\,\mathrm{T\,m^{2}}$.
  \item For a coil of $N$ turns, the \textbf{flux linkage} is $N\Phi$.
\end{itemize}

\subsection{Three ways flux can change}
Since $\Phi = BA\cos\theta$, any of these can induce an emf:
\begin{enumerate}
  \item Change $B$ (switch a nearby electromagnet on/off; move a magnet closer).
  \item Change $A$ (stretch a loop; slide a rod so the enclosed area grows).
  \item Change $\theta$ (rotate a coil in a magnetic field --- the generator idea).
\end{enumerate}

%======================================================================
\section{Faraday's law --- magnitude}

The magnitude of the average induced emf in a coil of $N$ turns is
\[
\mathcal{E} = N\,\frac{|\Delta\Phi|}{\Delta t}.
\]
In words: \textbf{emf $\propto$ how fast the flux linkage changes}.

A compact form that also encodes direction (see Lenz) is
\[
\mathcal{E} = -N\,\frac{\mathrm{d}\Phi}{\mathrm{d}t}.
\]
The minus sign is Lenz's law written into the formula.

\begin{mdframed}[style=tipbox]
\noindent\textbf{Exam habits.}
\begin{itemize}
  \item Broken circuit $\Rightarrow$ induced \textbf{emf} still exists; no sustained
        induced \textbf{current}.
  \item Closed circuit $\Rightarrow$ induced emf \emph{and} induced current
        $I=\mathcal{E}/R$.
  \item Soft-iron core: gathers and guides field lines $\Rightarrow$ larger
        $|\Delta\Phi|$ for the same magnet motion $\Rightarrow$ larger emf.
\end{itemize}
\end{mdframed}

%======================================================================
\section{Lenz's law --- direction}

\textbf{Lenz's law:} the induced current always flows so that its magnetic effect
\textbf{opposes the change} of flux that produced it.

This is energy conservation in disguise: if the induced current helped the change,
you would get free energy.

\begin{center}
\begin{tikzpicture}[scale=0.95]
  % magnet approaching coil
  \draw[thick,fill=posC!15] (-0.2,0.35) rectangle (1.4,0.95);
  \node[font=\scriptsize\bfseries] at (0.6,0.65) {N$\rightarrow$};
  \draw[-{Latex},very thick] (1.55,0.65) -- (2.2,0.65);
  \draw[thick] (2.5,-0.7) ellipse (0.55 and 0.95);
  \draw[thick] (2.5,0.25) arc (90:270:0.35 and 0.95);
  \node[font=\scriptsize,align=center] at (2.5,-1.35) {coil\\(closed)};
  \node[above,font=\small,align=center] at (1.3,1.4)
    {N-pole approaching $\Rightarrow$ flux ``into coil'' increasing\\
     induced current makes the near face a \textbf{N-pole} (repels magnet)};
\end{tikzpicture}
\end{center}

\paragraph{Practical recipe.}
\begin{enumerate}
  \item Decide whether flux through the coil is \emph{increasing} or \emph{decreasing},
        and in which direction the field points.
  \item Induced current creates a field that fights that change.
  \item Use the right-hand grip rule on the coil to find the current sense.
\end{enumerate}

\begin{mdframed}[style=misbox]
\noindent\textbf{Trap.}
Oppose the \emph{change}, not the field itself. If flux is decreasing, the
induced current tries to \textbf{maintain} the flux (same direction as the
original field).
\end{mdframed}

%======================================================================
\section{Motional emf}

\subsection{Cutting field lines}
A conductor of length $\ell$ moving at speed $v$ in a magnetic field $B$
(with $v$, $\ell$, and $B$ mutually perpendicular) has induced emf
\[
\mathcal{E} = B\ell v.
\]
More generally, $\mathcal{E}=(v B\sin\theta)\,\ell$, where $\theta$ is the angle
between $\vec v$ and $\vec B$.

\begin{center}
\begin{tikzpicture}[scale=1.0]
  \foreach \x in {0,0.45,...,3.6} {
    \foreach \y in {0,0.45,...,2.25} {
      \fill[gray] (\x,\y) circle (1.1pt);
    }
  }
  \node[font=\scriptsize] at (4.2,1.1) {$B$ out};
  \draw[very thick] (0.6,1.1) -- (3.0,1.1);
  \node[left,font=\small] at (0.6,1.1) {$P$};
  \node[right,font=\small] at (3.0,1.1) {$Q$};
  \draw[-{Latex},very thick,posC] (1.8,1.1) -- (1.8,0.15)
    node[below,font=\small] {$v$};
  \node[below,align=center,font=\small] at (1.8,-0.55)
    {Free charges in the rod feel $F=qvB$\\
     $\Rightarrow$ ends become charged $\Rightarrow$ motional emf};
\end{tikzpicture}
\end{center}

\paragraph{Direction.}
Use \textbf{Fleming's right-hand rule} (generator rule):
thumb = motion, first finger = field, second finger = induced current /
force on $+q$ inside the conductor.

\paragraph{Open vs closed.}
\begin{itemize}
  \item Open rod: charges separate until electric force balances magnetic force;
        a p.d.\ appears, but \textbf{no steady current}.
  \item Rod on conducting rails closing a loop: current flows; magnetic force
        on the current \textbf{opposes} the motion (you must do work to keep $v$
        constant --- that work becomes electrical energy).
\end{itemize}

\worked{2012}{32}{A}{47}{../2012_q32.png}{%
The falling copper rod cuts the Earth's field ($B$ out of the page), so a
motional emf appears across $PQ$: statement~(1) is true
($\mathcal{E}=B\ell v$).
There is \textbf{no closed circuit}, so no sustained induced current~(2) is
false. With no current there is no magnetic drag force, so the rod still falls
with acceleration $g$~(3) is false.
Hence only~(1) $\Rightarrow$ \textbf{A}.}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Sibling idea.}
Eddy currents in a solid metal plate entering a field act like many little loops:
they dissipate energy and produce magnetic braking. Slotting the plate reduces
eddy paths and weakens the braking.
\end{mdframed}

%======================================================================
\section{Simple generators}

\subsection{Rotating coil}
A coil of $N$ turns, area $A$, rotating at angular speed $\omega$ in uniform $B$
has flux $\Phi=BA\cos\omega t$ (suitable zero of $t$), so
\[
\mathcal{E}=NBA\omega\sin\omega t,
\qquad
\mathcal{E}_0 = NBA\omega.
\]
The emf is inherently \textbf{alternating}.

\subsection{AC output --- slip rings}
Two continuous slip rings + brushes keep each end of the coil connected to the
same terminal of the external circuit. Output to the load is ac.

\subsection{DC output --- commutator (split rings)}
A split-ring commutator reverses the coil-to-load connections every half turn,
so the current in the \textbf{load} stays in one direction (unsteady / pulsating
d.c.). Inside the coil the current still reverses naturally with rotation.

\begin{center}
\begin{tikzpicture}[scale=0.9]
  \draw[thick,fill=gray!20] (-2.2,-0.8) rectangle (-1.4,0.8);
  \node[font=\bfseries] at (-1.8,0) {S};
  \draw[thick,fill=gray!20] (1.4,-0.8) rectangle (2.2,0.8);
  \node[font=\bfseries] at (1.8,0) {N};
  \draw[thick] (-0.9,-0.55) rectangle (0.9,0.55);
  \node[font=\scriptsize] at (0,0) {coil};
  \draw[-{Latex}] (0.5,0.75) arc (40:-200:0.55);
  \node[font=\scriptsize] at (1.15,1.05) {rotate};
  \draw[thick] (0,-0.55) -- (0,-1.35);
  \draw[thick] (-0.25,-1.55) arc (180:0:0.25);
  \draw[thick] (0.25,-1.55) arc (0:-180:0.25);
  \node[font=\scriptsize,align=center] at (0,-2.05) {commutator\\(split rings)};
  \draw[thick] (-0.55,-1.55) -- (-0.55,-2.55) -- (0.55,-2.55) -- (0.55,-1.55);
  \draw[thick] (-0.25,-2.55) -- (-0.25,-3.0);
  \draw[thick] (0.25,-2.55) -- (0.25,-3.0);
  \draw[thick] (-0.55,-3.15) rectangle (0.55,-3.45);
  \node[font=\scriptsize] at (0,-3.3) {load};
\end{tikzpicture}
\end{center}

\paragraph{Factors that increase $|\mathcal{E}_0|$.}
Stronger $B$, more turns $N$, larger area $A$, higher rotation rate $\omega$,
soft-iron core (boosts effective $B$).

\worked{2022}{28}{D}{}{../2022_q28.png}{%
At the instant shown the coil is being driven clockwise: side $AB$ moves
downward. Induced current (Fleming RH) experiences a magnetic force that
\textbf{opposes} the motion, so the force on $AB$ is upward~(1) true
(Lenz).
The commutator reverses the \emph{connections to the load} each half-turn; it
does \textbf{not} ``reverse the current in the coil'' as statement~(2) claims
--- the coil current reverses because of rotation itself~(2) false.
With a split-ring commutator the load current is unidirectional but not steady
(unsteady d.c.)~(3) true.
Hence (1) and (3) $\Rightarrow$ \textbf{D}.}

%======================================================================
\section{QB examples (QB\_407)}

\qbtext{PHY14071101}{%
A coil of metal wire is placed perpendicular to a uniform magnetic field.
The coil is then rotated through $180^\circ$.
The magnitude of the average induced e.m.f.\ is independent of
\begin{enumerate}[label=\Alph*.,leftmargin=1.8em]
  \item the area of the coil;
  \item the flux density of the magnetic field;
  \item the number of turns of the coil;
  \item the resistance of the coil.
\end{enumerate}
}{D}{%
Initial flux $\Phi_i = BA$ (taking $\theta=0$). After a $180^\circ$ flip,
$\Phi_f = -BA$, so $|\Delta\Phi|=2BA$.
Average emf $\mathcal{E}=N|\Delta\Phi|/\Delta t=N(2BA)/\Delta t$.
This depends on $N$, $B$, $A$, and time, but \textbf{not} on resistance.
Resistance affects induced \emph{current} $I=\mathcal{E}/R$, not the emf itself
$\Rightarrow$ \textbf{D}.}

\qbtext{PHY14071105}{%
The flux linkage through a plane coil placed in a uniform magnetic field depends on
\begin{enumerate}[label=(\arabic*),leftmargin=1.8em]
  \item the resistance of the coil;
  \item the number of turns in the coil;
  \item the angle between the normal to the coil and the direction of the magnetic field.
\end{enumerate}
\begin{enumerate}[label=\Alph*.,leftmargin=1.8em]
  \item (1) only
  \item (2) only
  \item (1) and (2) only
  \item (2) and (3) only
\end{enumerate}
}{D}{%
Flux linkage $=N\Phi=NBA\cos\theta$. It depends on $N$ and on orientation
$\theta$, but not on resistance $\Rightarrow$ (2) and (3) $\Rightarrow$ \textbf{D}.}

\qbtext{PHY14071112}{%
A bar magnet is held close to a coil connected to a galvanometer.
In which case(s) will the galvanometer detect a current?
\begin{enumerate}[label=(\arabic*),leftmargin=1.8em]
  \item Move both the magnet and the coil to the right at the same speed.
  \item Move the magnet to the right and the coil to the left.
  \item Spin the magnet.
\end{enumerate}
\begin{enumerate}[label=\Alph*.,leftmargin=1.8em]
  \item (1) only
  \item (3) only
  \item (1) and (2) only
  \item (2) and (3) only
\end{enumerate}
}{D}{%
Induction needs \textbf{relative} motion that changes flux.
(1)~Same velocity $\Rightarrow$ no relative motion $\Rightarrow$ no change of flux
through the coil.
(2)~Relative approach/separation $\Rightarrow$ changing flux.
(3)~Spinning changes the field pattern through the coil $\Rightarrow$ changing
flux.
Hence (2) and (3) $\Rightarrow$ \textbf{D}.}

%======================================================================
\section{Formula summary}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Idea & Formula / rule \\
\midrule
Magnetic flux & $\Phi=BA\cos\theta$ \\
Flux linkage & $N\Phi$ \\
Faraday (magnitude) & $\mathcal{E}=N|\Delta\Phi|/\Delta t$ \\
Lenz & induced effects oppose the flux change \\
Motional emf & $\mathcal{E}=B\ell v$ (perpendicular case) \\
AC generator peak & $\mathcal{E}_0=NBA\omega$ \\
Induced current & $I=\mathcal{E}/R$ (closed circuit) \\
\bottomrule
\end{tabular}
\end{center}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Before the exam --- five checks.}
(1)~Is flux actually \emph{changing}?
(2)~Emf vs current --- is the circuit closed?
(3)~Lenz: oppose the \emph{change}, not the field.
(4)~Motional emf: open rod can have voltage with zero current.
(5)~Generator: slip rings $\to$ ac load; commutator $\to$ unsteady d.c.\ load.
\end{mdframed}

\clearpage
\section{Practice questions}

Attempt these closed-book. Answers are at the end.

\begin{mdframed}[style=pracbox]
\noindent\textbf{Practice --- conceptual}
\begin{enumerate}
  \item A coil sits in a uniform constant $B$-field. Does a steady current appear
        in the coil? Explain.
  \item Why does pulling a magnet out of a closed coil require more force than
        inserting it into an open-circuited coil (same speed)?
  \item A metal frame enters a uniform $B$-field at constant speed $v$. Why is
        there induced emf while entering, but none when the frame is wholly
        inside and still moving?
\end{enumerate}
\end{mdframed}

\begin{mdframed}[style=pracbox]
\noindent\textbf{Practice --- calculation}
A square loop of side $\ell=0.10\,\mathrm{m}$ and $N=50$ turns moves at
$v=2.0\,\mathrm{m\,s^{-1}}$ into a uniform field $B=0.40\,\mathrm{T}$ perpendicular
to the plane of the loop. Find the magnitude of the induced emf while the loop
is entering the field.
\end{mdframed}

\subsection*{Practice answers}
\begin{enumerate}
  \item No. $\Delta\Phi=0$ for constant $B$ and fixed orientation/area, so
        $\mathcal{E}=0$.
  \item Closed coil: induced current $\Rightarrow$ opposing magnetic force (Lenz).
        Open coil: emf but no current $\Rightarrow$ no magnetic drag.
  \item Entering: enclosed flux increases ($\Delta A$). Fully inside at constant
        $v$: $\Phi=BA$ constant $\Rightarrow$ no net emf (emfs on opposite sides cancel).
  \item While entering, $\mathcal{E}=NB\ell v=(50)(0.40)(0.10)(2.0)=4.0\,\mathrm{V}$.
\end{enumerate}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Classification note.}
In this topic folder, \texttt{2014\_q17}, \texttt{2014\_q18}, \texttt{2016\_q21},
and \texttt{2024\_q17} are ultrasound / sound-interference questions and are
omitted. \texttt{2014\_q28} is about $B=\mu_0 (N/L)I$ for a solenoid carrying
\textbf{constant} d.c.\ (magnetism, no induction) and is also omitted.
Real induction DSE items used above: \texttt{2012\_q32}, \texttt{2022\_q28}.
\end{mdframed}

\end{document}

