\pagestyle{fancy}
\fancyhf{}
\fancyhead[L]{\small HKDSE Physics --- AC \& transformers}
\fancyhead[R]{\small Active Physics Book~4, Ch.~22 \&~24}
\fancyfoot[C]{\thepage}
\renewcommand{\headrulewidth}{0.4pt}

\title{\textbf{Alternating Current and Transformers}\\[0.35em]
\large HKDSE Physics --- Electricity \& Magnetism}
\author{Teaching notes aligned with \emph{Active Physics} Book~4\\
(Ch.~22 AC essentials; Ch.~24 transformers)\\
Worked examples from HKDSE Paper~1A and QB\_408}
\date{}

\begin{document}
\maketitle
\tableofcontents
\vspace{0.5em}

\begin{mdframed}[style=tipbox]
\noindent\textbf{How these notes work.}
We first ask why mains electricity is alternating, then define peak and r.m.s.\
values and average power, then build transformers from Faraday's law and apply
them to efficiency and long-distance transmission. Blue boxes = worked DSE / QB
examples. Orange boxes = practice (answers last). Boxes do not break across pages.
\end{mdframed}

%======================================================================
\section{Why alternating current?}

\subsection{DC vs AC --- first principles}
\begin{itemize}
  \item \textbf{Direct current (d.c.):} charge flows one way. Battery voltage is
        essentially steady.
  \item \textbf{Alternating current (a.c.):} the direction of current reverses
        periodically. Mains voltage swings positive and negative.
\end{itemize}

Hong Kong mains: \textbf{$220\,\mathrm{V}$, $50\,\mathrm{Hz}$}.
The ``$220\,\mathrm{V}$'' is the \textbf{r.m.s.\ value} (see below), not the peak.
The frequency $50\,\mathrm{Hz}$ means the polarity reverses 100 times per second
(two reversals per cycle).

\subsection{The engineering reason for a.c.}
Transformers (next sections) change voltage \textbf{easily} only for a.c.,
because they need a \emph{changing} flux.
High-voltage transmission then cuts $I^{2}R$ losses in the cables.
That is why national grids run on a.c.

%======================================================================
\section{Sinusoidal voltage and current}

A simple a.c.\ generator produces (to a good approximation)
\[
V = V_0\sin\omega t,
\qquad
I = I_0\sin\omega t
\]
for a resistive load in phase with $V$. Here $V_0$ and $I_0$ are
\textbf{peak} (maximum) values, and $\omega=2\pi f$.

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[-{Latex}] (0,0) -- (7.2,0) node[right,font=\small] {$t$};
  \draw[-{Latex}] (0,-1.6) -- (0,1.8) node[above,font=\small] {$V$};
  \draw[dashed] (0,1.2) -- (6.8,1.2);
  \draw[dashed] (0,-1.2) -- (6.8,-1.2);
  \node[right,font=\scriptsize] at (6.85,1.2) {$V_0$};
  \node[right,font=\scriptsize] at (6.85,-1.2) {$-V_0$};
  \draw[very thick,blue!50!black,domain=0:6.6,samples=200]
    plot (\x,{1.2*sin(deg(\x*pi/1.65))});
  \draw[dashed,posC] (0,{1.2/1.414}) -- (6.8,{1.2/1.414});
  \node[font=\scriptsize,posC] at (5.4,1.05) {$V_{\mathrm{rms}}$};
  \node[below,font=\small] at (3.3,-1.85)
    {Average of $V$ over a cycle is $0$; heating depends on $V^{2}$.};
\end{tikzpicture}
\end{center}

%======================================================================
\section{Peak vs r.m.s.}

\subsection{Why r.m.s.\ exists}
Over a full cycle the average of $\sin\omega t$ is zero, so
$\langle V\rangle=0$ and $\langle I\rangle=0$. That does \textbf{not} mean
``no heating'': a resistor still gets hot because power depends on $I^{2}$.

Define the \textbf{root-mean-square} value so that a resistive heater dissipates
the same average power as it would on a steady d.c.\ of that value:
\[
V_{\mathrm{rms}} = \sqrt{\langle V^{2}\rangle},
\qquad
I_{\mathrm{rms}} = \sqrt{\langle I^{2}\rangle}.
\]

\subsection{Sinusoidal a.c.}
For $V=V_0\sin\omega t$,
\[
\boxed{V_{\mathrm{rms}} = \dfrac{V_0}{\sqrt{2}} \approx 0.707\,V_0},
\qquad
I_{\mathrm{rms}} = \dfrac{I_0}{\sqrt{2}}.
\]
HK mains: $V_{\mathrm{rms}}=220\,\mathrm{V}$ $\Rightarrow$
$V_0=220\sqrt{2}\approx 311\,\mathrm{V}$.

\begin{mdframed}[style=misbox]
\noindent\textbf{Trap.}
CRO traces show \textbf{peak} (or peak-to-peak). Transformer formulae and
``$220\,\mathrm{V}$ mains'' use \textbf{r.m.s.} unless stated otherwise.
Convert before using turns ratios.
\end{mdframed}

\subsection{Average power in a resistor}
\[
\langle P\rangle = I_{\mathrm{rms}}^{2} R = \frac{V_{\mathrm{rms}}^{2}}{R}
= V_{\mathrm{rms}} I_{\mathrm{rms}}.
\]
Note carefully: $\langle P\rangle\neq\langle V\rangle\langle I\rangle$
(both averages on the right are zero for pure a.c.).

\worked{2014}{30}{B}{57}{../2014_q30.png}{%
For d.c.: $P=V^{2}/R=10^{2}/R$.
For a.c.\ with power $\tfrac12 P$:
$V_{\mathrm{rms}}^{2}/R=\tfrac12\cdot 10^{2}/R$
$\Rightarrow V_{\mathrm{rms}}^{2}=50$
$\Rightarrow V_{\mathrm{rms}}=5\sqrt{2}\,\mathrm{V}$ $\Rightarrow$ \textbf{B}.}

\worked{2017}{29}{A}{68}{../2017_q29.png}{%
(1)~$V_0=V_{\mathrm{rms}}\sqrt{2}=110\sqrt{2}\approx 156\,\mathrm{V}$ true.
(2)~$P=V_{\mathrm{rms}}^{2}/R=110^{2}/100=121\,\mathrm{W}$ true.
(3)~If $V_{\mathrm{rms}}$ doubles, $P\propto V^{2}$ becomes \textbf{four} times,
not double $\Rightarrow$ false.
Hence (1) and (2) only $\Rightarrow$ \textbf{A}.}

%======================================================================
\section{Transformers --- from Faraday's law}

\subsection{Structure and principle}
A transformer has:
\begin{itemize}
  \item a \textbf{primary} coil (input),
  \item a \textbf{secondary} coil (output),
  \item usually a laminated \textbf{soft-iron core} linking the two.
\end{itemize}

Alternating primary current $\Rightarrow$ alternating flux in the core
$\Rightarrow$ changing flux through the secondary $\Rightarrow$ induced
secondary emf (Faraday).

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[thick] (-0.1,-1.3) -- (-0.1,1.3);
  \draw[thick] (0.1,-1.3) -- (0.1,1.3);
  % primary
  \foreach \y in {-0.9,-0.55,-0.2,0.15,0.5,0.85} {
    \draw[thick] (-0.1,\y) arc (90:270:0.28);
  }
  % secondary
  \foreach \y in {-0.7,-0.25,0.2,0.65} {
    \draw[thick] (0.1,\y) arc (90:-90:0.35);
  }
  \draw[-{Latex}] (-1.6,0.9) -- (-0.95,0.9);
  \draw[-{Latex}] (-0.95,-0.9) -- (-1.6,-0.9);
  \node[font=\scriptsize,align=center] at (-2.15,0) {a.c.\\primary};
  \node[font=\scriptsize] at (-0.75,1.35) {$N_p$};
  \node[font=\scriptsize] at (0.85,1.35) {$N_s$};
  \draw[-{Latex}] (1.55,0.75) -- (2.3,0.75);
  \draw[-{Latex}] (2.3,-0.75) -- (1.55,-0.75);
  \node[font=\scriptsize,align=center] at (2.85,0) {load\\secondary};
  \node[below,font=\small] at (0.4,-1.7)
    {Soft-iron core guides flux; works properly for \textbf{a.c.\ only}.};
\end{tikzpicture}
\end{center}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Why not d.c.?}
Steady primary current $\Rightarrow$ steady flux $\Rightarrow$
$\Delta\Phi/\Delta t=0$ $\Rightarrow$ no secondary emf (after the initial switch-on
transient).
\end{mdframed}

\subsection{Ideal turns ratio}
If flux leakage is negligible,
\[
\frac{V_p}{V_s} = \frac{N_p}{N_s}.
\]
(All $V$ mean r.m.s.\ unless a question says peak.)

\subsection{Ideal power and current}
For $100\%$ efficiency, $P_{\mathrm{in}}=P_{\mathrm{out}}$:
\[
V_p I_p = V_s I_s
\qquad\Rightarrow\qquad
\frac{I_s}{I_p} = \frac{N_p}{N_s} = \frac{V_p}{V_s}.
\]
Compact ideal summary:
\[
\boxed{\dfrac{N_p}{N_s}=\dfrac{V_p}{V_s}=\dfrac{I_s}{I_p}}.
\]

\subsection{Step-up and step-down}
\begin{itemize}
  \item \textbf{Step-up:} $N_s>N_p$ $\Rightarrow$ $V_s>V_p$ and $I_s<I_p$.
  \item \textbf{Step-down:} $N_s<N_p$ $\Rightarrow$ $V_s<V_p$ and $I_s>I_p$.
\end{itemize}

\worked{2023}{29}{A}{55}{../2023_q29.png}{%
Secondary peak on CRO is $V_{s0}=11\,\mathrm{V}$, so
$V_{s,\mathrm{rms}}=11/\sqrt{2}$.
Primary $V_{p,\mathrm{rms}}=220\,\mathrm{V}$, $N_p=2000$.
\[
\frac{N_s}{N_p}=\frac{V_s}{V_p}
\Rightarrow
N_s=2000\cdot\frac{11/\sqrt{2}}{220}
=\frac{2000\times 11}{220\sqrt{2}}
\approx 70.7
\approx 71.
\]
$\Rightarrow$ \textbf{A}.
(Choosing $N_s=100$ would wrongly treat $11\,\mathrm{V}$ as r.m.s.)}

\worked{2019}{29}{C}{}{../2019_q29.png}{%
Each bulb is rated $12\,\mathrm{V}$, $24\,\mathrm{W}$. For the bulbs to work at
rated voltage the secondary must supply $12\,\mathrm{V}$ (r.m.s.).
With primary on $220\,\mathrm{V}$ mains (typical arrangement in the figure),
\[
\frac{N_p}{N_s}=\frac{V_p}{V_s}=\frac{220}{12}\approx 18.3
\approx 20:1
\]
(nearest option) $\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Efficiency and losses}

\subsection{Definition}
\[
\eta = \frac{P_{\mathrm{out}}}{P_{\mathrm{in}}}\times 100\%
= \frac{V_s I_s}{V_p I_p}\times 100\%.
\]
If $\eta\neq 100\%$, you \textbf{cannot} use $V_p I_p=V_s I_s$. You still use
$V_p/V_s\approx N_p/N_s$ if leakage is small, but currents follow power:
$V_p I_p\cdot\eta = V_s I_s$.

\subsection{Where energy goes}
\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Loss mechanism & Improvement \\
\midrule
Coil resistance ($I^{2}R$ heating) & thicker wires \\
Eddy currents in core & laminated core \\
Magnetization / hysteresis of core & soft-iron core \\
Flux leakage & close coupling; good core geometry \\
\bottomrule
\end{tabular}
\end{center}

\begin{mdframed}[style=misbox]
\noindent\textbf{Trap (laminated core).}
Eddy-current losses reduce transmitted \emph{power} (and thus $I_s$), but the
secondary \emph{voltage} is set mainly by the rate of flux change / turns ratio,
not by eddy heating directly.
\end{mdframed}

\worked{2016}{31}{D}{53}{../2016_q31.png}{%
Two bulbs at rated $22\,\mathrm{W}$ each $\Rightarrow$
$P_{\mathrm{out}}=44\,\mathrm{W}$.
$P_{\mathrm{in}}=V_p I_p=220\times 0.25=55\,\mathrm{W}$.
\[
\eta=\frac{44}{55}\times 100\%=80\%
\Rightarrow\textbf{D}.
\]}

\qbtext{PHY14081101}{%
The primary coil of a transformer is connected to the $220\,\mathrm{V}$ mains.
A lamp on the secondary works at its rated value `$110\,\mathrm{V}$, $100\,\mathrm{W}$'.
If the primary current is $0.5\,\mathrm{A}$, what is the efficiency of the
transformer?
\begin{enumerate}[label=\Alph*.,leftmargin=1.8em]
  \item $19\%$
  \item $55\%$
  \item $80\%$
  \item $91\%$
\end{enumerate}
}{D}{%
$P_{\mathrm{out}}=100\,\mathrm{W}$ (rated, and working at rated value).
$P_{\mathrm{in}}=V_p I_p=220\times 0.5=110\,\mathrm{W}$.
\[
\eta=\frac{100}{110}\times 100\%\approx 90.9\%\approx 91\%
\Rightarrow\textbf{D}.
\]}

\worked{2017}{30}{D}{54}{../2017_q30.png}{%
Ten bulbs in parallel, each $1.5\,\mathrm{W}$ at rated value
$\Rightarrow P_{\mathrm{out}}=15\,\mathrm{W}$.
$\eta=70\%$ $\Rightarrow P_{\mathrm{in}}=15/0.70\approx 21.43\,\mathrm{W}$.
$I_p=P_{\mathrm{in}}/V_p=21.43/220\approx 0.097\,\mathrm{A}$ $\Rightarrow$ \textbf{D}.}

%======================================================================
\section{Power transmission}

\subsection{The $I^{2}R$ argument}
Power delivered to users: $P\approx VI$.
For fixed $P$, raising transmission voltage $V$ lowers current $I=P/V$.
Cable loss:
\[
P_{\mathrm{loss}}=I^{2} R_{\mathrm{cable}}.
\]
Smaller $I$ $\Rightarrow$ much smaller heating loss.

\subsection{Why a.c.\ for the grid}
Step-up transformers raise voltage at the power station; step-down transformers
bring it back to safe domestic levels near users. Doing the same with d.c.\ was
historically much harder (modern HVDC exists, but HKDSE focuses on the a.c.\
transformer story).

\begin{mdframed}[style=tipbox]
\noindent\textbf{Exam wording.}
``Electricity is transmitted at high voltage because \ldots''
--- the useful answer is almost always: \textbf{reduce current, hence reduce
$I^{2}R$ loss}. ``Transmit more energy per unit charge'' is about voltage as
energy per charge, but that alone does not explain why we bother stepping up.
\end{mdframed}

\qbtext{PHY14081103}{%
Electricity is transmitted at a high voltage over long distances because
\begin{enumerate}[label=(\arabic*),leftmargin=1.8em]
  \item a larger amount of energy can be transmitted per unit charge;
  \item energy can be transmitted at a fast rate;
  \item less power is lost through heating during transmission.
\end{enumerate}
\begin{enumerate}[label=\Alph*.,leftmargin=1.8em]
  \item (1) only
  \item (3) only
  \item (1) and (2) only
  \item (2) and (3) only
\end{enumerate}
}{B}{%
The standard HKDSE point is reduced heating loss via smaller $I$~(3).
(1)~and~(2) are not the accepted reasoning for choosing high-voltage
transmission in this syllabus context $\Rightarrow$ \textbf{B}.}

