\section{Formula summary}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Idea & Formula / rule \\
\midrule
Sinusoidal r.m.s. & $V_{\mathrm{rms}}=V_0/\sqrt{2}$,\quad $I_{\mathrm{rms}}=I_0/\sqrt{2}$ \\
Average power (resistor) & $\langle P\rangle=V_{\mathrm{rms}}I_{\mathrm{rms}}=V_{\mathrm{rms}}^{2}/R$ \\
Ideal transformer & $N_p/N_s=V_p/V_s=I_s/I_p$ \\
Efficiency & $\eta=P_{\mathrm{out}}/P_{\mathrm{in}}$;\quad $\eta V_p I_p=V_s I_s$ \\
Cable loss & $P_{\mathrm{loss}}=I^{2}R$ \\
\bottomrule
\end{tabular}
\end{center}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Before the exam --- five checks.}
(1)~Peak or r.m.s.?
(2)~Ideal ($\eta=100\%$) or not?
(3)~Series/parallel bulbs: total $P_{\mathrm{out}}$?
(4)~Step-up raises $V$ and lowers $I$.
(5)~Transformers need \emph{changing} primary current (a.c.).
\end{mdframed}

