\section{Typical cases and problem-solving}

\subsection{Case A --- changing $B$ through a fixed coil}
Direction: Lenz. Magnitude:
\[
\mathcal{E}=NA\frac{|\Delta B|}{\Delta t}
\]
(if $A$ and orientation fixed). Soft-iron core increases the effective flux
change for the same external magnet.

\subsection{Case B --- magnet approaching / leaving a coil}
Same as Lenz section. Speed up the magnet $\Rightarrow$ larger $|\mathcal{E}|$.
Insert soft iron $\Rightarrow$ larger $|\mathcal{E}|$. Open circuit $\Rightarrow$ emf
but no current (and no magnetic drag on the magnet from induced current).

\subsection{Case C --- rod on rails (flux from changing area)}

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \foreach \x in {0.0,0.35,...,4.2} {
    \foreach \y in {0.0,0.35,...,2.1} {
      \fill[gray] (\x,\y) circle (0.9pt);
    }
  }
  \node[font=\scriptsize] at (4.7,1.05) {$B$ into page};
  \draw[very thick] (0.3,0.3) -- (0.3,2.0);
  \draw[very thick] (0.3,0.3) -- (3.8,0.3);
  \draw[very thick] (0.3,2.0) -- (3.8,2.0);
  \draw[very thick,posC] (2.5,0.3) -- (2.5,2.0);
  \node[font=\scriptsize,posC] at (2.5,2.25) {rod, $v\rightarrow$};
  \draw[-{Latex},very thick,posC] (2.5,1.15) -- (3.3,1.15);
  \draw[thick] (0.3,1.15) -- (-0.5,1.15);
  \draw[thick] (-0.7,0.85) rectangle (-0.2,1.45);
  \node[font=\scriptsize] at (-0.45,1.15) {$R$};
  \node[below,align=center,font=\small] at (2.0,-0.45)
    {Area of loop grows: $\Phi=B\cdot(\ell x)$ increases\\
     $\mathcal{E}=B\ell v$,\quad $I=\mathcal{E}/R$,\quad drag $F=BIL=B^{2}\ell^{2}v/R$};
\end{tikzpicture}
\end{center}

\noindent\textbf{Worked rails example.}
$B=0.50\,\mathrm{T}$ into the page, $\ell=0.20\,\mathrm{m}$,
$v=3.0\,\mathrm{m\,s^{-1}}$, $R=2.0\,\Omega$.
\[
\mathcal{E}=B\ell v=(0.50)(0.20)(3.0)=0.30\,\mathrm{V},
\quad
I=\frac{0.30}{2.0}=0.15\,\mathrm{A}.
\]
Power dissipated in $R$: $P=I^{2}R=(0.15)^{2}(2.0)=0.045\,\mathrm{W}$.
External force needed for constant $v$:
$F=BIL=(0.50)(0.15)(0.20)=0.015\,\mathrm{N}$,
and check $Fv=(0.015)(3.0)=0.045\,\mathrm{W}=P$ (energy conserved).

\subsection{Case D --- coil / frame wholly inside a uniform field}
If $B$, $A$, and orientation are all constant, $\Delta\Phi=0$ even if the object
is moving. Motional emfs on opposite sides cancel. \textbf{No net emf}, no net
current.

\subsection{Search coil (brief)}
A small coil used to study a \textbf{varying} $B$-field (e.g.\ inside a solenoid
driven by a.c.). Induced peak emf relates to peak field by
$\mathcal{E}_0=\omega N A B_0$ for $B=B_0\sin\omega t$. A steady Earth's field
does not affect the reading (no change). Orient the coil face-on to the field
for maximum signal.

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistakes.}
\begin{itemize}
  \item Treating a steady field through a coil as ``inducing something''.
  \item Assuming emf $\Rightarrow$ current without a closed path.
  \item Opposing the field instead of the \emph{change} (Lenz).
  \item Forgetting $|\Delta\Phi|=2BA$ on a $180^\circ$ flip.
  \item Saying the commutator reverses current \emph{in the coil} (it reverses
        the load connections).
  \item Using peak voltage with a transformer / turns formula that expects r.m.s.
        (that trap belongs mainly to the AC topic, but CRO peaks appear in
        induction labs too).
\end{itemize}
\end{mdframed}

