\subsection{Worked numerical example --- changing $B$}

\begin{center}
\begin{tikzpicture}[scale=1.0]
  \draw[thick] (0,0) ellipse (1.4 and 0.55);
  \draw[thick] (-1.4,0) -- (-1.4,-0.15);
  \draw[thick] (1.4,0) -- (1.4,-0.15);
  \draw[thick] (0,-0.15) ellipse (1.4 and 0.55);
  \foreach \a in {0,40,...,320} {
    \draw[-{Latex},negC!70!black] (\a:0.35) -- (\a:1.05);
  }
  \node[font=\scriptsize] at (0,-1.0) {coil, $N$ turns, area $A$};
  \node[font=\scriptsize,negC] at (2.2,0.2) {$B(t)$};
  \node[below,align=center,font=\small] at (0,-1.45)
    {Uniform $B$ through the coil increases with time\\
     $\Rightarrow$ $\Phi=BA$ rises $\Rightarrow$ induced emf};
\end{tikzpicture}
\end{center}

\noindent\textbf{Example.}
A flat coil has $N=200$ turns and area $A=1.5\times 10^{-3}\,\mathrm{m^{2}}$.
It sits face-on in a uniform field that increases from
$0.20\,\mathrm{T}$ to $0.50\,\mathrm{T}$ in $0.10\,\mathrm{s}$.
The coil resistance is $R=4.0\,\Omega$.

\begin{enumerate}[leftmargin=1.6em]
  \item Find the average induced emf.
  \item Find the average induced current if the coil is shorted through $R$.
\end{enumerate}

\noindent\textbf{Solution.}
\[
|\Delta\Phi| = A|\Delta B| = (1.5\times 10^{-3})(0.30)=4.5\times 10^{-4}\,\mathrm{Wb}.
\]
\[
\mathcal{E}=N\frac{|\Delta\Phi|}{\Delta t}
=200\cdot\frac{4.5\times 10^{-4}}{0.10}=0.90\,\mathrm{V}.
\]
\[
I=\frac{\mathcal{E}}{R}=\frac{0.90}{4.0}=0.225\,\mathrm{A}.
\]
Lenz: the induced current produces a field opposing the \emph{increase} of $B$,
i.e.\ opposite to the original field direction.

