  \draw[thick] (3.9,-0.55) arc (-90:90:0.25 and 0.55);
  \draw[thick] (4.3,0.5) -- (5.0,0.5) -- (5.0,-0.2);
  \draw[thick] (4.3,-0.55) -- (5.0,-0.55) -- (5.0,-0.2);
  \draw[thick] (4.85,-0.35) -- (5.15,-0.05);
  \node[font=\scriptsize] at (3.4,-1.25) {coil 1 + battery};
  \node[below,align=center,font=\small] at (2.5,-1.7)
    {Close switch: flux through coil~2 rises briefly $\Rightarrow$ kick on G\\
     Steady current in coil~1: flux constant $\Rightarrow$ G returns to zero\\
     Open switch: flux falls $\Rightarrow$ kick the other way};
\end{tikzpicture}
\end{center}

\noindent Crucial exam point: a \textbf{steady} current in coil~1 does \emph{not}
induce a steady current in coil~2. Only the \emph{change} (on or off, or a.c.)
matters. Lenz: when you switch on, coil~2 opposes the new flux; when you switch
off, coil~2 tries to maintain the dying flux.

